  const s = String(iban || '').replace(/\s+/g, '').toUpperCase();
  if (!/^[A-Z]{2}\d{2}[A-Z0-9]{10,30}$/.test(s)) return false;
  const rearranged = s.slice(4) + s.slice(0, 4);
  let rest = 0;
  for (const ch of rearranged) {
    const v = /[A-Z]/.test(ch) ? String(ch.charCodeAt(0) - 55) : ch;
    for (const digit of v) rest = (rest * 10 + Number(digit)) % 97;
  }
  return rest === 1;
}

// Österreichische UID: ATU + 8 Ziffern mit Prüfziffer
function atUidValid(uid) {
  const s = String(uid || '').replace(/\s+/g, '').toUpperCase();
  if (!/^ATU\d{8}$/.test(s)) return false;
  const d = s.slice(3).split('').map(Number);
  let sum = 0;
  for (let i = 0; i < 7; i++) {
    let v = d[i];
    if (i % 2 === 1) { v *= 2; v = Math.floor(v / 10) + (v % 10); }
    sum += v;
  }
  const check = (10 - ((sum + 4) % 10)) % 10;
  return check === d[7];
}

function validateExtraction(x, { today = new Date() } = {}) {
  const errors = [];
  const warnings = [];
  if (!x || typeof x !== 'object') return { errors: ['Kein Ergebnis vorhanden'], warnings, checks: {} };

  const financial = ['rechnung', 'gutschrift'].includes(x.doc_type);
  const commercial = financial || ['bestellung', 'auftragsbestaetigung', 'angebot'].includes(x.doc_type);

  if (x.doc_type === 'sonstiges') warnings.push('Dokumenttyp nicht erkannt');
  if (!x.issuer || !x.issuer.name) errors.push('Aussteller fehlt');
  if (commercial && !x.document_number) errors.push('Belegnummer fehlt');
  if (financial && !x.document_date) errors.push('Belegdatum fehlt');

  for (const f of ['document_date', 'delivery_date', 'due_date']) {
    if (x[f] != null && !isValidDate(x[f])) errors.push(`Ungültiges Datum in ${f}: ${x[f]}`);
  }
  if (isValidDate(x.document_date)) {
    const d = new Date(`${x.document_date}T00:00:00Z`);
    const days = (d - today) / 86400000;
    if (days > 2) errors.push(`Belegdatum liegt in der Zukunft: ${x.document_date}`);
    if (days < -730) warnings.push(`Belegdatum ist älter als zwei Jahre: ${x.document_date}`);
  }

  if (x.currency != null && !/^[A-Z]{3}$/.test(x.currency)) warnings.push(`Unbekannte Währung: ${x.currency}`);
  if (financial && x.currency == null) warnings.push('Währung fehlt');

  const t = x.totals || {};
  const lines = Array.isArray(x.line_items) ? x.line_items : [];
  if (financial && !isNum(t.gross)) errors.push('Bruttobetrag fehlt');
  if (isNum(t.net) && isNum(t.tax) && isNum(t.gross) && Math.abs(round2(t.net + t.tax) - t.gross) > TOLERANCE) {
    errors.push(`Summen passen nicht: netto ${t.net} + Steuer ${t.tax} ≠ brutto ${t.gross}`);
  }
  const lineNets = lines.map((l) => l.net_amount).filter(isNum);
  if (lineNets.length > 0 && lineNets.length === lines.length && isNum(t.net)) {
    const sum = round2(lineNets.reduce((a, b) => a + b, 0));
    if (Math.abs(sum - t.net) > Math.max(TOLERANCE, lines.length * 0.01)) {
      warnings.push(`Positionen ergeben ${sum}, Nettosumme ist ${t.net}`);
    }
  }
  for (const [i, l] of lines.entries()) {
    if (isNum(l.quantity) && isNum(l.unit_price) && isNum(l.net_amount)) {
      const calc = round2(l.quantity * l.unit_price);
      if (Math.abs(calc - l.net_amount) > Math.max(TOLERANCE, Math.abs(l.net_amount) * 0.005)) {
        warnings.push(`Position ${l.position || i + 1}: Menge × Preis = ${calc}, angegeben ${l.net_amount}`);
      }
    }
    if (isNum(l.tax_rate) && ![0, 5, 7, 10, 13, 19, 20].includes(l.tax_rate)) {
      warnings.push(`Position ${l.position || i + 1}: ungewöhnlicher Steuersatz ${l.tax_rate} %`);
    }
  }
  if (x.doc_type !== 'gutschrift' && isNum(t.gross) && t.gross < 0) errors.push('Negativer Betrag auf einem Dokument, das keine Gutschrift ist');

  if (x.issuer && x.issuer.iban && !ibanValid(x.issuer.iban)) errors.push(`IBAN des Ausstellers ungültig: ${x.issuer.iban}`);
  for (const p of ['issuer', 'recipient']) {
    const uid = x[p] && x[p].vat_id;
    if (uid && /^ATU/i.test(uid.replace(/\s+/g, '')) && !atUidValid(uid)) warnings.push(`UID-Nummer (${p}) hat falsche Prüfziffer: ${uid}`);
  }

  if (Array.isArray(x.anomalies) && x.anomalies.length > 0) warnings.push(...x.anomalies.map((a) => `KI-Hinweis: ${a}`));

  const conf = x.field_confidence || {};
  const confValues = Object.values(conf).filter(isNum);
  const minConfidence = confValues.length ? Math.min(...confValues) : 0;
  return { errors, warnings, checks: { minConfidence, gross: isNum(t.gross) ? t.gross : null, lines: lines.length } };
}

if (typeof module !== 'undefined') module.exports = { validateExtraction, ibanValid, atUidValid, isValidDate };

// Entscheidungslogik: Braucht es den Prüf-Agenten? Darf das Ergebnis automatisch durch?
// Grundsatz: Im Zweifel entscheidet ein Mensch. Automatisch geht nur durch,
// was eindeutig, plausibel und (wo nötig) von einem zweiten Agenten bestätigt ist.

const norm = (v) => (v == null ? null : String(v).toLowerCase().replace(/[\s.\-/]/g, ''));
const numEq = (a, b) => (a == null && b == null) || (typeof a === 'number' && typeof b === 'number' && Math.abs(a - b) <= 0.05);

function needsVerification({ extraction, validation, settings }) {
  const reasons = [];
  const gross = validation.checks.gross;
  if (validation.warnings.length > 0) reasons.push('Warnungen der Prüfregeln');
  if (!(validation.checks.minConfidence >= settings.confidence_auto)) reasons.push('KI war sich nicht sicher genug');
  if (gross != null && !(Math.abs(gross) < settings.verify_above_gross)) reasons.push('Betrag über Prüfgrenze');
  if ((settings.always_verify_types || []).includes(extraction.doc_type)) reasons.push(`Dokumenttyp ${extraction.doc_type} wird immer geprüft`);
  return { required: reasons.length > 0, reasons };
}

// Vergleicht die kritischen Felder zweier Ergebnisse (Vier-Augen-Prinzip zweier Agenten).
function compareCritical(a, b) {
  const diffs = [];
  if (!a || !b) return ['Vergleich nicht möglich'];
  if (a.doc_type !== b.doc_type) diffs.push(`Dokumenttyp: ${a.doc_type} / ${b.doc_type}`);
  if (norm(a.document_number) !== norm(b.document_number)) diffs.push(`Belegnummer: ${a.document_number} / ${b.document_number}`);
  if (a.document_date !== b.document_date) diffs.push(`Belegdatum: ${a.document_date} / ${b.document_date}`);
  if (norm(a.issuer && a.issuer.iban) !== norm(b.issuer && b.issuer.iban)) diffs.push('IBAN des Ausstellers weicht ab');
  for (const k of ['net', 'tax', 'gross']) {
    if (!numEq(a.totals && a.totals[k], b.totals && b.totals[k])) diffs.push(`Summe ${k}: ${a.totals && a.totals[k]} / ${b.totals && b.totals[k]}`);
  }
  const la = (a.line_items || []).length;
  const lb = (b.line_items || []).length;
  if (la !== lb) diffs.push(`Anzahl Positionen: ${la} / ${lb}`);
  return diffs;
}

// Endentscheidung. verification = {ok, data} | {ok:false, error} | null (nicht nötig)
// Streng: Automatisch geht nur durch, was ohne jede Auffälligkeit ist.
function decide({ extraction, validation, verification, verificationRequired, duplicates, ibanStatus, settings, revalidate }) {
  const reasons = [];
  let final = extraction;

  // Ungültige Einstellungen dürfen die Schutzgrenzen nie still abschalten
  for (const k of ['confidence_auto', 'verify_above_gross', 'review_above_gross']) {
    if (!Number.isFinite(settings[k])) reasons.push(`Einstellung ${k} ist ungültig: alles geht zur Prüfung`);
  }

  if (validation.errors.length > 0) reasons.push(...validation.errors.map((e) => `Prüfregel: ${e}`));
  if (duplicates && duplicates.length > 0) {
    reasons.push(`Mögliches Duplikat: gleiche Belegnummer bereits vorhanden (${duplicates.join(', ')})`);
  }
  if (Array.isArray(extraction.anomalies) && extraction.anomalies.length > 0) {
    reasons.push(...extraction.anomalies.map((a) => `KI-Hinweis: ${a}`));
  }

  // Schutz vor Rechnungsbetrug: neue Bankverbindung oder neuer Lieferant mit Bankverbindung
  if (['rechnung', 'gutschrift'].includes(extraction.doc_type)) {
    if (ibanStatus === 'neu') reasons.push('Bankverbindung des Ausstellers ist neu (bisher andere IBAN)');
    if (ibanStatus === 'neuer_aussteller') reasons.push('Erste Rechnung dieses Ausstellers mit Bankverbindung');
  }

  if (verificationRequired) {
    if (!verification || !verification.ok) {
      reasons.push(`Prüf-Agent nicht verfügbar: ${(verification && verification.error) || 'kein Ergebnis'}`);
    } else {
      const v = verification.data;
      const diffs = compareCritical(extraction, v.corrected);
      const findings = (v.findings || []).filter((f) => f.severity === 'fehler' || f.severity === 'warnung');
      if (v.verdict === 'unsicher') reasons.push('Prüf-Agent: Dokument erlaubt keine sichere Aussage');
      if (v.verdict === 'korrigiert') reasons.push('Prüf-Agent hat Werte korrigiert');
      if (diffs.length > 0) reasons.push(...diffs.map((d) => `Agenten uneinig: ${d}`));
      if (findings.length > 0) reasons.push(...findings.map((f) => `Prüf-Agent: ${f.field}: ${f.problem}`));
      // Bei Übereinstimmung der kritischen Felder gilt die Fassung des Prüfers; sie muss alle Regeln erfüllen
      if (diffs.length === 0) {
        final = v.corrected;
        const re = revalidate ? revalidate(final) : null;
        if (re) {
          reasons.push(...re.errors.map((e) => `Prüfregel nach Prüfung: ${e}`));
          reasons.push(...re.warnings.filter((w) => !w.startsWith('KI-Hinweis')).map((w) => `Warnung nach Prüfung: ${w}`));
        }
      }
    }
  } else if (validation.warnings.length > 0) {
    reasons.push(...validation.warnings.map((w) => `Warnung: ${w}`));
  }

  const gross = validation.checks.gross;
  if (gross != null && Math.abs(gross) >= settings.review_above_gross) {
    reasons.push(`Betrag ${gross} über Freigabegrenze ${settings.review_above_gross}: Vier-Augen-Prinzip`);
  }
  if (extraction.doc_type === 'sonstiges') reasons.push('Dokumenttyp nicht erkannt');

  return { outcome: reasons.length === 0 ? 'auto' : 'review', reasons: [...new Set(reasons)], final };
}

if (typeof module !== 'undefined') module.exports = { needsVerification, compareCritical, decide };

// ---- Knotenlogik ----

const ctx = { ...$json };
const d = decide({ extraction: ctx.extraction, validation: ctx.validation, verification: ctx.verification,
                   verificationRequired: ctx.verificationRequired, duplicates: ctx.duplicates, ibanStatus: ctx.ibanStatus, settings: ctx.settings,
                   revalidate: (x) => validateExtraction(x) });
const usage = (ctx.calls || []).reduce((a, c) => ({ input: a.input + (c.input || 0), output: a.output + (c.output || 0) }), { input: 0, output: 0 });
return { json: { job_id: ctx.job.job_id, worker: ctx.worker, outcome: d.outcome, reasons: d.reasons, final: d.final,
  extraction: ctx.extraction, verification: ctx.verification || null,
  validation: { ...ctx.validation, pruef_agent_gruende: ctx.verificationReasons, duplikate: ctx.duplicates, iban_status: ctx.ibanStatus },
  models: [...new Set(ctx.models)], usage, calls: ctx.calls } };
